sigset_t wait_set;
siginfo_t info_out;
struct timespec timer = { .tv_sec = 5, .tv_nsec = 0 };

// Initialize and specify signals to catch
sigemptyset(&wait_set);
sigaddset(&wait_set, SIGUSR1);
sigaddset(&wait_set, SIGHUP);

// rt_sigtimedwait system call (often wrapped by sigtimedwait)
int sig_received = sigtimedwait(
    &wait_set,        /* const sigset_t *restrict set */
    &info_out,         /* siginfo_t *_Nullable restrict info */
    &timer             /* const struct timespec *restrict timeout */
);

if (sig_received > 0) {
    /* Process info_out */
    int sender_pid = info_out.si_pid;
}
